-- Apply Phase 4B to an existing easner-website project (generated by supabase/build-apply-phase4b.mjs; do not edit).
-- Run once in the Supabase SQL editor, after the earlier setup. It is one transaction: it applies fully or not at all.
-- Contains: 20261118120000_blog_lifecycle.sql

begin;

-- >>> 20261118120000_blog_lifecycle.sql
-- Phase 4B: the content lifecycle (docs/blog-and-admin-plan.md §4 Posts and Editor, §7 Phase 4).
--
--   1. Scheduling: schedule_post, unschedule_post, and publish_post learns to run for a due scheduled post when the
--      secret key (service role) calls it. The admin's cron route does that every 5 minutes.
--   2. Revisions: a milestone row on submit, a word count per revision, autosave checkpoints written by the database
--      (throttled, bounded), and a restore that lands in the draft only.
--   3. Edit lock and presence: a soft lock on the post row (2 minute expiry, kept alive by a heartbeat) and a presence
--      table, both written only through functions. Polled by the admin: it does not need Realtime.
--   4. Redirects: add_blog_redirect validates; direct inserts and updates are closed; a slug change (or a new post
--      taking a slug) clears any redirect that would shadow it.

-- ---------------------------------------------------------------------------------------------------------------
-- Columns
-- ---------------------------------------------------------------------------------------------------------------

alter type public.blog_revision_kind add value if not exists 'submit';

alter table public.blog_posts
  add column scheduled_by uuid references auth.users (id) on delete set null,
  -- Where the post goes back to when the schedule is removed.
  add column scheduled_from public.blog_post_status;

alter table public.blog_revisions add column word_count integer;

alter table public.blog_redirects
  add column created_by uuid default auth.uid() references auth.users (id) on delete set null;

create index blog_posts_due_idx on public.blog_posts (scheduled_for) where status = 'scheduled';

-- ---------------------------------------------------------------------------------------------------------------
-- Revisions: word count, autosave checkpoints, bounded retention
-- ---------------------------------------------------------------------------------------------------------------

create function public.blog_doc_word_count(doc jsonb)
returns integer
language sql
immutable
set search_path = ''
as $$
  select case
    when doc is null or btrim(public.blog_doc_text(doc)) = '' then 0
    else coalesce(array_length(regexp_split_to_array(btrim(public.blog_doc_text(doc)), '\s+'), 1), 0)
  end
$$;

create function public.blog_revisions_fill()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.word_count := public.blog_doc_word_count(new.content);
  return new;
end
$$;

create trigger blog_revisions_fill before insert on public.blog_revisions
  for each row execute function public.blog_revisions_fill();

update public.blog_revisions set word_count = public.blog_doc_word_count(content);

-- Autosave checkpoints are written here, not by the browser: at most one every 5 minutes per post, and never the
-- same text twice in a row. Only the newest 40 are kept (milestones, which are the publish, submit and restore
-- rows, are never pruned).
create function public.blog_posts_checkpoint()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  latest public.blog_revisions;
begin
  if new.draft_content is null or public.blog_in_trusted_write() then
    return new;
  end if;
  if new.draft_content is not distinct from old.draft_content
     and new.title is not distinct from old.title
     and new.excerpt is not distinct from old.excerpt then
    return new;
  end if;

  select * into latest from public.blog_revisions r where r.post_id = new.id order by r.created_at desc limit 1;
  if found and latest.content is not distinct from new.draft_content and latest.title is not distinct from new.title
     and latest.excerpt is not distinct from new.excerpt then
    return new;
  end if;
  if exists (
    select 1 from public.blog_revisions r
    where r.post_id = new.id and r.kind = 'autosave' and r.created_at > now() - interval '5 minutes'
  ) then
    return new;
  end if;

  insert into public.blog_revisions (post_id, content, title, excerpt, kind, created_by)
  values (new.id, new.draft_content, new.title, new.excerpt, 'autosave', auth.uid());

  delete from public.blog_revisions r
  where r.post_id = new.id and r.kind = 'autosave'
    and r.id not in (
      select k.id from public.blog_revisions k where k.post_id = new.id and k.kind = 'autosave'
      order by k.created_at desc limit 40
    );
  return new;
end
$$;

create trigger blog_posts_checkpoint after update of draft_content, title, excerpt on public.blog_posts
  for each row execute function public.blog_posts_checkpoint();

-- Submitting for review leaves a milestone: this is the version the Editor was asked to review.
create or replace function public.submit_for_review(p_post_id uuid)
returns public.blog_posts
language plpgsql
security definer
set search_path = ''
as $$
declare
  post public.blog_posts;
begin
  if not public.is_admin_member() then
    raise exception 'Not allowed.' using errcode = 'insufficient_privilege';
  end if;
  select * into post from public.blog_posts where id = p_post_id for update;
  if not found then
    raise exception 'Post not found.' using errcode = 'no_data_found';
  end if;
  if not (public.is_blog_editor() or post.created_by = auth.uid()) then
    raise exception 'You can only submit your own posts.' using errcode = 'insufficient_privilege';
  end if;
  if post.status not in ('draft', 'changes_requested') then
    raise exception 'This post can''t be submitted from its current status.' using errcode = 'check_violation';
  end if;
  if char_length(btrim(post.title)) = 0 or coalesce(post.draft_content, post.content) is null then
    raise exception 'Add a title and some content before submitting.' using errcode = 'check_violation';
  end if;

  perform set_config('easner.blog_trusted_write', 'on', true);
  update public.blog_posts p set status = 'in_review' where p.id = p_post_id returning * into post;
  perform set_config('easner.blog_trusted_write', 'off', true);

  insert into public.blog_revisions (post_id, content, title, excerpt, kind)
  values (post.id, coalesce(post.draft_content, post.content), post.title, post.excerpt, 'submit');

  perform public.log_admin_activity('post.submitted', 'blog_post', post.id::text, jsonb_build_object('slug', post.slug));
  return post;
end
$$;

-- Restore copies a version into the working draft and never touches the live post. If the version equals what is
-- live there is nothing to publish, so the draft is cleared. What was in the draft first is kept as a checkpoint,
-- so a restore can be undone.
create or replace function public.restore_revision(p_revision_id uuid)
returns public.blog_posts
language plpgsql
security definer
set search_path = ''
as $$
declare
  rev public.blog_revisions;
  post public.blog_posts;
  before_doc jsonb;
begin
  select * into rev from public.blog_revisions where id = p_revision_id;
  if not found then
    raise exception 'Revision not found.' using errcode = 'no_data_found';
  end if;
  if not public.can_edit_blog_post(rev.post_id) then
    raise exception 'You can''t edit this post.' using errcode = 'insufficient_privilege';
  end if;

  select * into post from public.blog_posts p where p.id = rev.post_id for update;
  if post.status = 'archived' then
    raise exception 'Restore the archived post before restoring a version.' using errcode = 'check_violation';
  end if;

  before_doc := coalesce(post.draft_content, post.content);
  if before_doc is not null and before_doc is distinct from rev.content then
    insert into public.blog_revisions (post_id, content, title, excerpt, kind)
    values (post.id, before_doc, post.title, post.excerpt, 'autosave');
  end if;

  perform set_config('easner.blog_trusted_write', 'on', true);
  update public.blog_posts p set
    draft_content = case when rev.content is not distinct from p.content then null else rev.content end,
    title = coalesce(rev.title, p.title),
    excerpt = rev.excerpt
  where p.id = rev.post_id
  returning * into post;
  perform set_config('easner.blog_trusted_write', 'off', true);

  insert into public.blog_revisions (post_id, content, title, excerpt, kind)
  values (post.id, rev.content, rev.title, rev.excerpt, 'restore');

  perform public.log_admin_activity('post.revision_restored', 'blog_post', post.id::text,
    jsonb_build_object('revision_id', rev.id));

  return post;
end
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- Guard: schedule fields, lock fields, and the slug lock for scheduled posts
-- ---------------------------------------------------------------------------------------------------------------

create or replace function public.blog_posts_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- The lock functions touch only the lock columns: that is not an edit, so updated_at (which autosave compares) stays.
  if tg_op = 'UPDATE' and coalesce(current_setting('easner.blog_lock_write', true), '') = 'on' then
    new.updated_at := old.updated_at;
    new.updated_by := old.updated_by;
    return new;
  end if;

  new.updated_at := now();
  new.updated_by := coalesce(auth.uid(), new.updated_by);

  -- Server jobs (service role, no user) and the trusted functions write freely.
  if public.blog_in_trusted_write() or auth.uid() is null then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.created_by is distinct from auth.uid() then
      raise exception 'A post is created by the person signed in.' using errcode = 'insufficient_privilege';
    end if;
    if new.status <> 'draft' then
      raise exception 'New posts start as drafts. Use submit_for_review() and publish_post().' using errcode = 'insufficient_privilege';
    end if;
    if new.content is not null or new.content_text is not null or new.published_at is not null
       or new.content_modified_at is not null or new.summary is not null
       or new.scheduled_for is not null or new.scheduled_by is not null or new.scheduled_from is not null
       or new.locked_by is not null or new.locked_at is not null then
      raise exception 'Published fields are set by publish_post().' using errcode = 'insufficient_privilege';
    end if;
    new.word_count := 0;
    new.reading_minutes := 0;
  else
    if new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
      raise exception 'A post''s creator can''t change.' using errcode = 'insufficient_privilege';
    end if;
    if new.status is distinct from old.status then
      raise exception 'The status changes through submit_for_review(), request_changes(), publish_post(), schedule_post(), unpublish_post() and archive_post().'
        using errcode = 'insufficient_privilege';
    end if;
    if new.content is distinct from old.content
       or new.content_text is distinct from old.content_text
       or new.summary is distinct from old.summary
       or new.published_at is distinct from old.published_at
       or new.content_modified_at is distinct from old.content_modified_at
       or new.word_count is distinct from old.word_count
       or new.reading_minutes is distinct from old.reading_minutes then
      raise exception 'Published fields are set by publish_post().' using errcode = 'insufficient_privilege';
    end if;
    if new.scheduled_for is distinct from old.scheduled_for
       or new.scheduled_by is distinct from old.scheduled_by
       or new.scheduled_from is distinct from old.scheduled_from then
      raise exception 'The schedule changes through schedule_post() and unschedule_post().' using errcode = 'insufficient_privilege';
    end if;
    if new.locked_by is distinct from old.locked_by or new.locked_at is distinct from old.locked_at then
      raise exception 'The edit lock changes through claim_post_lock().' using errcode = 'insufficient_privilege';
    end if;
    -- A published or scheduled post's URL is part of what the web has linked to (or is about to be): owners only.
    if new.slug is distinct from old.slug and (old.published_at is not null or old.status = 'scheduled')
       and not public.is_admin_owner() then
      raise exception 'This post has been published or scheduled, so only an owner can change its URL.'
        using errcode = 'insufficient_privilege';
    end if;
  end if;

  if not public.is_blog_editor() then
    if (tg_op = 'INSERT' and (new.featured or new.featured_rank is not null))
       or (tg_op = 'UPDATE' and (new.featured is distinct from old.featured
                                 or new.featured_rank is distinct from old.featured_rank)) then
      raise exception 'Only an editor can feature a post.' using errcode = 'insufficient_privilege';
    end if;
  end if;

  return new;
end
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- Scheduling
-- ---------------------------------------------------------------------------------------------------------------

-- The version hash is also needed when the cron publishes (service role, no member): same value, one more caller.
create or replace function public.blog_post_version_hash(p_post_id uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select case when public.is_admin_member() or (auth.uid() is null and coalesce(auth.role(), '') = 'service_role') then
    (select md5(coalesce(p.title, '') || '|' || coalesce(p.excerpt, '') || '|' || coalesce(coalesce(p.draft_content, p.content)::text, ''))
     from public.blog_posts p where p.id = p_post_id)
  end
$$;

-- The rules every route to "live" shares: content, title, category, cover, and the second Editor for flagged posts.
-- p_actor is the Editor standing behind this publication (the caller, or whoever scheduled it).
create function public.blog_assert_publishable(p_post public.blog_posts, p_actor uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  approvers uuid[];
begin
  if coalesce(p_post.draft_content, p_post.content) is null then
    raise exception 'This post has no content yet.' using errcode = 'check_violation';
  end if;
  if char_length(btrim(p_post.title)) = 0 then
    raise exception 'Add a title before publishing.' using errcode = 'check_violation';
  end if;
  if p_post.category_id is null then
    raise exception 'Choose a category before publishing.' using errcode = 'check_violation';
  end if;
  if p_post.cover_path is null or char_length(btrim(coalesce(p_post.cover_alt, ''))) = 0 then
    raise exception 'Add a cover image with alt text before publishing.' using errcode = 'check_violation';
  end if;

  if p_post.claims_flagged then
    if p_post.created_by = p_actor then
      raise exception 'This post makes claims that need a second editor (fees, rates, insurance, regulation or comparisons). Its author can''t publish it.'
        using errcode = 'check_violation';
    end if;
    approvers := public.blog_approving_editors(p_post.id);
    if not (p_actor = any (approvers)) then
      approvers := approvers || p_actor;
    end if;
    if cardinality(approvers) < 2 then
      raise exception 'This post makes claims about fees, rates, insurance, regulation or competitors. A second Editor has to approve it.'
        using errcode = 'check_violation';
    end if;
  end if;
end
$$;

-- An Editor schedules a post for a time in the future (UTC). Rescheduling is the same call. The slug locks as for a
-- published post; the post leaves the public views because they only show status = 'published'.
create function public.schedule_post(p_post_id uuid, p_at timestamptz)
returns public.blog_posts
language plpgsql
security definer
set search_path = ''
as $$
declare
  post public.blog_posts;
begin
  if not public.is_blog_editor() then
    raise exception 'Only an editor or owner can schedule.' using errcode = 'insufficient_privilege';
  end if;
  if p_at is null or p_at <= now() + interval '1 minute' then
    raise exception 'Choose a time in the future.' using errcode = 'check_violation';
  end if;

  select * into post from public.blog_posts where id = p_post_id for update;
  if not found then
    raise exception 'Post not found.' using errcode = 'no_data_found';
  end if;
  if post.status not in ('draft', 'in_review', 'changes_requested', 'scheduled') then
    raise exception 'Only a post that is not live yet can be scheduled.' using errcode = 'check_violation';
  end if;

  perform public.blog_assert_publishable(post, auth.uid());

  -- The scheduler's approval counts for this version, exactly as it does when publishing.
  insert into public.blog_post_approvals (post_id, approver, version_hash)
  values (post.id, auth.uid(), public.blog_post_version_hash(post.id))
  on conflict do nothing;

  perform set_config('easner.blog_trusted_write', 'on', true);
  update public.blog_posts p set
    status = 'scheduled',
    scheduled_for = p_at,
    scheduled_by = auth.uid(),
    scheduled_from = case when post.status = 'scheduled' then p.scheduled_from else post.status end
  where p.id = p_post_id
  returning * into post;
  perform set_config('easner.blog_trusted_write', 'off', true);

  perform public.log_admin_activity('post.scheduled', 'blog_post', post.id::text,
    jsonb_build_object('slug', post.slug, 'at', p_at));
  return post;
end
$$;

create function public.unschedule_post(p_post_id uuid)
returns public.blog_posts
language plpgsql
security definer
set search_path = ''
as $$
declare
  post public.blog_posts;
begin
  if not public.is_blog_editor() then
    raise exception 'Only an editor or owner can unschedule.' using errcode = 'insufficient_privilege';
  end if;
  select * into post from public.blog_posts where id = p_post_id for update;
  if not found then
    raise exception 'Post not found.' using errcode = 'no_data_found';
  end if;
  if post.status <> 'scheduled' then
    raise exception 'This post isn''t scheduled.' using errcode = 'check_violation';
  end if;

  perform set_config('easner.blog_trusted_write', 'on', true);
  update public.blog_posts p set
    status = coalesce(p.scheduled_from, 'draft'),
    scheduled_for = null,
    scheduled_by = null,
    scheduled_from = null
  where p.id = p_post_id
  returning * into post;
  perform set_config('easner.blog_trusted_write', 'off', true);

  perform public.log_admin_activity('post.unscheduled', 'blog_post', post.id::text, jsonb_build_object('slug', post.slug));
  return post;
end
$$;

-- publish_post, now also the way a due scheduled post goes live. Called with the secret key (service role, no user),
-- it only publishes a post whose status is 'scheduled' and whose time has come, on behalf of the Editor who
-- scheduled it, and it is idempotent: the row lock makes a second run see 'published' and refuse. Called by an Editor,
-- it behaves as before (publish now, which also clears a schedule).
create or replace function public.publish_post(
  p_post_id uuid,
  p_significant_update boolean default true,
  p_content_text text default null,
  p_word_count integer default null,
  p_reading_minutes integer default null,
  p_summary text default null
)
returns public.blog_posts
language plpgsql
security definer
set search_path = ''
as $$
declare
  post public.blog_posts;
  actor uuid := auth.uid();
  by_schedule boolean := false;
  doc jsonb;
  doc_text text;
  words integer;
  first_publish boolean;
  first_at timestamptz;
begin
  if actor is null and coalesce(auth.role(), '') = 'service_role' then
    by_schedule := true;
  elsif not public.is_blog_editor() then
    raise exception 'Only an editor or owner can publish.' using errcode = 'insufficient_privilege';
  end if;

  select * into post from public.blog_posts where id = p_post_id for update;
  if not found then
    raise exception 'Post not found.' using errcode = 'no_data_found';
  end if;

  if by_schedule then
    if post.status <> 'scheduled' or post.scheduled_for is null or post.scheduled_for > now() then
      raise exception 'This post isn''t due.' using errcode = 'check_violation';
    end if;
    actor := post.scheduled_by;
    if actor is null or not exists (
      select 1 from public.admin_members m where m.user_id = actor and m.role in ('owner', 'editor')
    ) then
      raise exception 'The Editor who scheduled this post can no longer publish it.' using errcode = 'insufficient_privilege';
    end if;
  end if;

  if post.status = 'archived' then
    raise exception 'Restore an archived post before publishing it.' using errcode = 'check_violation';
  end if;

  perform public.blog_assert_publishable(post, actor);

  doc := coalesce(post.draft_content, post.content);
  doc_text := public.blog_doc_text(doc);
  words := coalesce(array_length(regexp_split_to_array(btrim(doc_text), '\s+'), 1), 0);
  if btrim(doc_text) = '' then
    words := 0;
  end if;
  first_publish := post.published_at is null;
  -- A scheduled post is dated to its time, not to when the cron got to it.
  first_at := case when by_schedule then post.scheduled_for else now() end;

  insert into public.blog_post_approvals (post_id, approver, version_hash)
  values (post.id, actor, public.blog_post_version_hash(post.id))
  on conflict do nothing;

  perform set_config('easner.blog_trusted_write', 'on', true);
  update public.blog_posts p set
    content = doc,
    draft_content = null,
    content_text = coalesce(p_content_text, doc_text),
    summary = p_summary,
    word_count = coalesce(p_word_count, words),
    reading_minutes = coalesce(p_reading_minutes, greatest(1, ceil(words / 230.0)::integer)),
    status = 'published',
    published_at = coalesce(p.published_at, first_at),
    scheduled_for = null,
    scheduled_by = null,
    scheduled_from = null,
    content_modified_at = case
      when first_publish or p_significant_update then first_at
      else p.content_modified_at
    end
  where p.id = p_post_id
  returning * into post;
  perform set_config('easner.blog_trusted_write', 'off', true);

  insert into public.blog_revisions (post_id, content, title, excerpt, kind, created_by)
  values (post.id, post.content, post.title, post.excerpt, 'publish', actor);

  insert into public.admin_activity (actor, action, entity, entity_id, meta)
  values (actor,
    case when first_publish then 'post.published' else 'post.updated' end,
    'blog_post', post.id::text,
    jsonb_build_object('slug', post.slug, 'significant', p_significant_update, 'scheduled', by_schedule));

  return post;
end
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- Edit lock and presence
-- ---------------------------------------------------------------------------------------------------------------

create table public.blog_post_presence (
  post_id uuid not null references public.blog_posts (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  seen_at timestamptz not null default now(),
  primary key (post_id, user_id)
);

alter table public.blog_post_presence enable row level security;
create policy "Members read presence" on public.blog_post_presence
  for select to authenticated using (public.is_admin_member());
revoke all on public.blog_post_presence from anon;
revoke insert, update, delete, truncate on public.blog_post_presence from authenticated;

create function public.blog_member_label(p_user_id uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(nullif(m.name, ''), m.email) from public.admin_members m where m.user_id = p_user_id
$$;

-- Takes the lock, keeps it (the heartbeat is this same call every ~30 seconds), or reports who has it.
-- A lock nobody refreshed for 2 minutes is free. Editors and owners may take over a live lock.
-- Returns {acquired, took_over, holder_id, holder_name, locked_at, can_take_over}.
create function public.claim_post_lock(p_post_id uuid, p_take_over boolean default false)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  post public.blog_posts;
  me uuid := auth.uid();
  free boolean;
  took boolean := false;
begin
  if not public.is_admin_member() or not public.can_edit_blog_post(p_post_id) then
    raise exception 'You can''t edit this post.' using errcode = 'insufficient_privilege';
  end if;
  select * into post from public.blog_posts where id = p_post_id for update;
  if not found then
    raise exception 'Post not found.' using errcode = 'no_data_found';
  end if;

  free := post.locked_by is null or post.locked_by = me or post.locked_at is null
          or post.locked_at < now() - interval '2 minutes';

  if not free then
    if p_take_over and public.is_blog_editor() then
      took := true;
    else
      return jsonb_build_object(
        'acquired', false, 'took_over', false,
        'holder_id', post.locked_by, 'holder_name', public.blog_member_label(post.locked_by),
        'locked_at', post.locked_at, 'can_take_over', public.is_blog_editor());
    end if;
  end if;

  perform set_config('easner.blog_lock_write', 'on', true);
  update public.blog_posts p set locked_by = me, locked_at = now() where p.id = p_post_id returning * into post;
  perform set_config('easner.blog_lock_write', 'off', true);

  insert into public.blog_post_presence (post_id, user_id, seen_at) values (p_post_id, me, now())
  on conflict (post_id, user_id) do update set seen_at = excluded.seen_at;

  if took then
    perform public.log_admin_activity('post.lock_taken_over', 'blog_post', p_post_id::text, '{}'::jsonb);
  end if;

  return jsonb_build_object(
    'acquired', true, 'took_over', took,
    'holder_id', me, 'holder_name', public.blog_member_label(me),
    'locked_at', post.locked_at, 'can_take_over', public.is_blog_editor());
end
$$;

create function public.release_post_lock(p_post_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_admin_member() then
    raise exception 'Not allowed.' using errcode = 'insufficient_privilege';
  end if;
  perform set_config('easner.blog_lock_write', 'on', true);
  update public.blog_posts p set locked_by = null, locked_at = null
  where p.id = p_post_id and p.locked_by = auth.uid();
  perform set_config('easner.blog_lock_write', 'off', true);
  delete from public.blog_post_presence where post_id = p_post_id and user_id = auth.uid();
end
$$;

-- Someone reading a post (or waiting for a lock to free up) shows up in the top bar too.
create function public.touch_post_presence(p_post_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_admin_member() then
    raise exception 'Not allowed.' using errcode = 'insufficient_privilege';
  end if;
  insert into public.blog_post_presence (post_id, user_id, seen_at) values (p_post_id, auth.uid(), now())
  on conflict (post_id, user_id) do update set seen_at = excluded.seen_at;
  delete from public.blog_post_presence where seen_at < now() - interval '1 day';
end
$$;

-- Who is on the post right now (seen in the last 2 minutes) and who holds the lock.
create function public.blog_post_viewers(p_post_id uuid)
returns table (user_id uuid, name text, avatar_path text, seen_at timestamptz, holds_lock boolean)
language sql
stable
security definer
set search_path = ''
as $$
  select pr.user_id,
         public.blog_member_label(pr.user_id),
         (select a.avatar_path from public.blog_authors a where a.member_id = pr.user_id limit 1),
         pr.seen_at,
         coalesce(p.locked_by = pr.user_id and p.locked_at > now() - interval '2 minutes', false)
  from public.blog_post_presence pr
  join public.blog_posts p on p.id = pr.post_id
  where public.is_admin_member() and pr.post_id = p_post_id and pr.seen_at > now() - interval '2 minutes'
  order by pr.seen_at desc
$$;

-- ---------------------------------------------------------------------------------------------------------------
-- Redirects
-- ---------------------------------------------------------------------------------------------------------------

-- The only way to add one by hand. Direct inserts and updates are closed below; removing one stays a plain delete.
create function public.add_blog_redirect(p_from_slug text, p_to_post_id uuid)
returns public.blog_redirects
language plpgsql
security definer
set search_path = ''
as $$
declare
  target public.blog_posts;
  redirect public.blog_redirects;
  v_from text := lower(btrim(coalesce(p_from_slug, '')));
begin
  if not public.is_blog_editor() then
    raise exception 'Only an editor or owner can add a redirect.' using errcode = 'insufficient_privilege';
  end if;
  if not public.blog_post_slug_ok(v_from) then
    raise exception 'That isn''t a valid URL ending. Use lowercase letters, numbers and hyphens.' using errcode = 'check_violation';
  end if;
  if exists (select 1 from public.blog_posts p where p.slug = v_from) then
    raise exception 'A post already lives at that URL, so it can''t redirect.' using errcode = 'check_violation';
  end if;
  if exists (select 1 from public.blog_redirects r where r.from_slug = v_from) then
    raise exception 'That URL already redirects somewhere. Remove the old redirect first.' using errcode = 'unique_violation';
  end if;
  select * into target from public.blog_posts p where p.id = p_to_post_id;
  if not found or target.status <> 'published' then
    raise exception 'A redirect has to point to a published post.' using errcode = 'check_violation';
  end if;

  insert into public.blog_redirects (from_slug, to_post_id, created_by)
  values (v_from, target.id, auth.uid())
  returning * into redirect;

  perform public.log_admin_activity('redirect.added', 'blog_redirect', v_from,
    jsonb_build_object('from', v_from, 'to', target.slug));
  return redirect;
end
$$;

create function public.blog_redirects_log_delete()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.log_admin_activity('redirect.removed', 'blog_redirect', old.from_slug,
    jsonb_build_object('from', old.from_slug));
  return old;
end
$$;

create trigger blog_redirects_log_delete after delete on public.blog_redirects
  for each row execute function public.blog_redirects_log_delete();

drop policy "Editors add redirects" on public.blog_redirects;
drop policy "Editors change redirects" on public.blog_redirects;

-- A published post that changes slug keeps its old URL as a 301. Any post that takes a slug (a new post, a rename)
-- clears a redirect from that slug, because a redirect never shadows a live URL.
create or replace function public.blog_posts_slug_redirect()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' and new.slug is distinct from old.slug and old.published_at is not null then
    insert into public.blog_redirects (from_slug, to_post_id)
    values (old.slug, new.id)
    on conflict (from_slug) do update set to_post_id = excluded.to_post_id, created_at = now();
    perform public.log_admin_activity('post.slug_changed', 'blog_post', new.id::text,
      jsonb_build_object('from', old.slug, 'to', new.slug));
  end if;
  delete from public.blog_redirects where from_slug = new.slug;
  return new;
end
$$;

drop trigger blog_posts_slug_redirect on public.blog_posts;
create trigger blog_posts_slug_redirect after insert or update of slug on public.blog_posts
  for each row execute function public.blog_posts_slug_redirect();

-- ---------------------------------------------------------------------------------------------------------------
-- Grants
-- ---------------------------------------------------------------------------------------------------------------

revoke execute on function
  public.blog_doc_word_count(jsonb),
  public.blog_revisions_fill(),
  public.blog_posts_checkpoint(),
  public.blog_assert_publishable(public.blog_posts, uuid),
  public.blog_member_label(uuid),
  public.schedule_post(uuid, timestamptz),
  public.unschedule_post(uuid),
  public.claim_post_lock(uuid, boolean),
  public.release_post_lock(uuid),
  public.touch_post_presence(uuid),
  public.blog_post_viewers(uuid),
  public.add_blog_redirect(text, uuid),
  public.blog_redirects_log_delete(),
  public.publish_post(uuid, boolean, text, integer, integer, text)
from public, anon;

grant execute on function
  public.schedule_post(uuid, timestamptz),
  public.unschedule_post(uuid),
  public.claim_post_lock(uuid, boolean),
  public.release_post_lock(uuid),
  public.touch_post_presence(uuid),
  public.blog_post_viewers(uuid),
  public.add_blog_redirect(text, uuid),
  public.publish_post(uuid, boolean, text, integer, integer, text)
to authenticated;

-- The cron route calls publish_post with the secret key.
grant execute on function public.publish_post(uuid, boolean, text, integer, integer, text) to service_role;
-- Internal helpers stay internal.
revoke execute on function public.blog_assert_publishable(public.blog_posts, uuid), public.blog_member_label(uuid) from authenticated;

commit;
